import { ref, computed, type Ref, type ComputedRef } from 'vue';

/**
 * Defines a searchable accordion section.
 * - `titleKeys`: i18n translation keys for the section heading/subtitle
 * - `childKeys`: i18n translation keys for items inside the section (toggles, labels, etc.)
 */
export interface SectionSearchEntry {
  titleKeys: string[];
  childKeys: string[];
}

export interface AccordionSearchReturn {
  /** Current search query (reactive) */
  searchQuery: Ref<string>;
  /** Map of section key → matched boolean (reactive) */
  matchedSections: Ref<Record<string, boolean>>;
  /** Current expanded/collapsed state per section (reactive) */
  expandedSections: Ref<Record<string, boolean>>;
  /** Whether any section matches the current search (computed) */
  hasAnyMatch: ComputedRef<boolean>;
  /**
   * Run a search. Pass the search string and a translate function.
   * The translate function is called at search time so it works with
   * both Options API (`this.$t`) and Composition API (`useI18n().t`).
   */
  handleSearch: (searchItem: string, t: (key: string) => string) => void;
  /** Returns true when the section should be visible (no search or matched) */
  isSectionVisible: (sectionKey: string) => boolean;
  /** Returns true when the section matched the current search */
  isSectionMatched: (sectionKey: string) => boolean;
}

/**
 * Reusable composable for filtering accordion sections by search query.
 *
 * Searches against **translated** section titles/subtitles and child item labels.
 * Matching sections are auto-expanded; non-matching sections are hidden.
 * Clearing the search restores the original expand/collapse state.
 *
 * @param registry - Map of section keys to their searchable translation keys
 * @param defaults - Initial expanded/collapsed state per section key
 *
 * @example
 * ```ts
 * // In Options API component:
 * setup() {
 *   const accordionSearch = useAccordionSearch(MY_REGISTRY, { section1: true });
 *   return { ...accordionSearch };
 * }
 * // In template or methods, call:
 * //   handleSearch(searchTerm, $t)
 * ```
 */
export function useAccordionSearch(
  registry: Record<string, SectionSearchEntry>,
  defaults: Record<string, boolean>,
): AccordionSearchReturn {
  const searchQuery = ref('');
  const matchedSections = ref<Record<string, boolean>>({});
  const expandedSections = ref<Record<string, boolean>>({ ...defaults });
  let savedExpandedState: Record<string, boolean> | null = null;

  const hasAnyMatch = computed(() => {
    if (!searchQuery.value) return true;
    return Object.values(matchedSections.value).some((v) => v);
  });

  function handleSearch(searchItem: string, t: (key: string) => string) {
    searchQuery.value = searchItem;

    // Empty search — restore original expanded states
    if (!searchItem) {
      matchedSections.value = {};
      if (savedExpandedState) {
        expandedSections.value = { ...savedExpandedState };
        savedExpandedState = null;
      }
      return;
    }

    // Save original expanded states on first search
    if (!savedExpandedState) {
      savedExpandedState = { ...expandedSections.value };
    }

    const query = searchItem.toLowerCase();
    const matched: Record<string, boolean> = {};

    for (const [sectionKey, entry] of Object.entries(registry)) {
      const titleMatch = entry.titleKeys.some((key) =>
        t(key).toLowerCase().includes(query),
      );

      const childMatch = entry.childKeys.some((key) =>
        t(key).toLowerCase().includes(query),
      );

      matched[sectionKey] = titleMatch || childMatch;
      expandedSections.value[sectionKey] = matched[sectionKey];
    }

    matchedSections.value = matched;
  }

  function isSectionVisible(sectionKey: string): boolean {
    if (!searchQuery.value) return true;
    return !!matchedSections.value[sectionKey];
  }

  function isSectionMatched(sectionKey: string): boolean {
    return !!matchedSections.value[sectionKey];
  }

  return {
    searchQuery,
    matchedSections,
    expandedSections,
    hasAnyMatch,
    handleSearch,
    isSectionVisible,
    isSectionMatched,
  };
}
